// Anchor navigation to the visible viewport, including Android standalone mode.
(()=>{const root=document.documentElement,nav=document.querySelector('.bottomnav'),header=document.querySelector('header');function size(){const v=window.visualViewport;root.style.setProperty('--app-height',(v?.height||window.innerHeight)+'px');root.style.setProperty('--viewport-top',(v?.offsetTop||0)+'px');root.style.setProperty('--nav-height',nav.getBoundingClientRect().height+'px');root.style.setProperty('--header-height',header.getBoundingClientRect().height+'px');}window.addEventListener('resize',size);window.addEventListener('pageshow',size);window.visualViewport?.addEventListener('resize',size);window.visualViewport?.addEventListener('scroll',size);if(window.ResizeObserver){const observer=new ResizeObserver(size);observer.observe(nav);observer.observe(header);}size();})();
